def test_writer_lock_is_released_by_os_after_process_death(storage):
    storage.root.mkdir()
    marker = storage.root.parent / "child-locked"
    program = (
        "import fcntl,sys,time\nfrom pathlib import Path\n"
        "with open(sys.argv[1], 'a') as stream:\n"
        " fcntl.flock(stream, fcntl.LOCK_EX)\n"
        " Path(sys.argv[2]).write_text('locked')\n"
        " time.sleep(30)\n"
    )
    child = subprocess.Popen([sys.executable, "-c", program, str(storage.root / ".worker.lock"), str(marker)])
    try:
        until = time.monotonic() + 5
        while not marker.exists() and time.monotonic() < until:
            assert child.poll() is None
            time.sleep(.01)
        assert marker.exists()
        with pytest.raises(MediaStoreError, match="writer_active"):
            with storage.worker_lock():
                pytest.fail("competing writer entered")
    finally:
        child.kill()
        child.wait(timeout=5)
    with storage.worker_lock():
        pass


def test_idle_read_timer_closes_real_descriptor_and_releases_transfer(storage, registry, monkeypatch):
    import central.media_store as module
    with storage.worker_lock():
        _, _, prepared = ready(storage)
        player, _, _ = grant(storage, registry, prepared.variant)
        monkeypatch.setattr(module, "_READ_SECONDS", 1)
        reader = storage.open_read(player["token"], prepared.variant.sha256)
        descriptor = reader._fd
        until = time.monotonic() + 3
        try:
            while time.monotonic() < until:
                try:
                    os.fstat(descriptor)
                except OSError:
                    break
                time.sleep(.02)
            else:
                pytest.fail("idle read descriptor remained open past its deadline")
        finally:
            reader.close()
        with storage.db.transaction() as conn:
            assert conn.execute("SELECT count(*) AS n FROM media_references WHERE owner LIKE 'transfer:%'").fetchone()["n"] == 0


@pytest.mark.parametrize("field", ["recipe_id", "asset_id", "original_sha1", "blob_variant"])
def test_recovery_rejects_mismatched_publication_journal(storage, monkeypatch, field):
    with storage.worker_lock():
        lease, _, prepared = staged(storage)
        monkeypatch.setattr(storage, "_rename", lambda *_: (_ for _ in ()).throw(Crash()))
        with pytest.raises(Crash):
            storage.publish(lease, prepared)
        with storage.repository.transaction() as conn:
            if field == "blob_variant":
                variant = prepared.variant.model_dump(mode="json")
                variant["width"] += 1
                conn.execute("UPDATE media_blobs SET variant=%s", (Jsonb(variant),))
            else:
                result = conn.execute("SELECT result FROM media_jobs WHERE id=%s", (lease.job_id,)).fetchone()["result"]
                result[field] = "wrong"
                conn.execute("UPDATE media_jobs SET result=%s WHERE id=%s", (Jsonb(result), lease.job_id))
    restarted = MediaStore(storage.repository, storage.root)
    with restarted.worker_lock():
        assert row(storage, "media_jobs", "id", lease.job_id)["state"] == "retry"
        assert row(storage, "media_blobs", "digest", prepared.variant.sha256) is None
        assert storage.repository.health()["accounted_bytes"] == 0
